using Microsoft.EntityFrameworkCore;
public class Inventory { public int ProductId { get; set; } public int Reserved { get; set; } }
public class Shipment { public int OrderId { get; set; } public string Status { get; set; } = ""; }
public class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<Inventory> Inventory => Set<Inventory>();
    public DbSet<Shipment> Shipments => Set<Shipment>();
}
